// Public Apple Root CA - G3 (DER). Not a secret.
// Source: https://www.apple.com/certificateauthority/AppleRootCA-G3.cer
// Apple's SignedDataVerifier expects this root when checking the x5c chain.

const APPLE_ROOT_CA_G3_B64 =
  '';

function decodeB64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const APPLE_ROOT_CERTIFICATES: Uint8Array[] = [decodeB64(APPLE_ROOT_CA_G3_B64)];
